package ir.coffevista.vista_native.features.chat.presentation.components

import android.content.Context
import org.json.JSONArray

/**
 * Index of the bundled frame-by-frame animated emoji (Lottie files under
 * `assets/emoji/animated`, generated by `tools/emoji/fetch_animated_emoji.py`).
 */
object AnimatedEmojiCatalog {
    private const val DIR = "emoji/animated"

    @Volatile
    private var available: Set<String>? = null

    fun assetPathFor(context: Context, emoji: String): String? {
        val index = available ?: loadIndex(context)
        val key = candidateKeys(emoji).firstOrNull { it in index } ?: return null
        return "$DIR/$key.json"
    }

    internal fun candidateKeys(emoji: String): List<String> {
        val codePoints = mutableListOf<Int>()
        var i = 0
        while (i < emoji.length) {
            val cp = emoji.codePointAt(i)
            codePoints += cp
            i += Character.charCount(cp)
        }
        val full = codePoints.joinToString("_") { it.toString(16) }
        val stripped = codePoints.filter { it != 0xFE0F }.joinToString("_") { it.toString(16) }
        return listOf(full, stripped).distinct()
    }

    private fun loadIndex(context: Context): Set<String> = synchronized(this) {
        available ?: runCatching {
            val text = context.applicationContext.assets.open("$DIR/index.json")
                .bufferedReader().use { it.readText() }
            val array = JSONArray(text)
            buildSet { for (n in 0 until array.length()) add(array.getString(n)) }
        }.getOrDefault(emptySet()).also { available = it }
    }
}
